// cheerio 最小 shim（Reelbox 内置）
//
// 为什么不用真的 cheerio：
//   drpy2 只用它做 jinja2 模板渲染（`cheerio.jinja2(tpl, obj)`），
//   真正的 HTML 解析走 pdfh/pdfa（宿主侧 jsoup 实现）。
//   完整 cheerio 体积 ~700KB，且在 npm CDN 上拿不到可用的 min 版。
//
// 导出形态要和 cheerio 一致：default 是一个对象。

var cheerio = {
    // drpy 模板渲染：把 {{key}} / {{a.b.c}} 替换成对象里的值
    jinja2: function (template, obj) {
        if (template == null) return "";
        if (obj == null) return String(template);
        return String(template).replace(/\{\{\s*([\w.]+)\s*\}\}/g, function (m, key) {
            var v = key.split(".").reduce(function (o, k) {
                return (o == null ? undefined : o[k]);
            }, obj);
            return v == null ? "" : String(v);
        });
    },

    // 兜底 load：返回一个空壳，避免调用方崩
    load: function (html) {
        return {
            text: function () { return String(html == null ? "" : html); },
            html: function () { return String(html == null ? "" : html); },
            find: function () {
                return { text: function () { return ""; }, attr: function () { return ""; }, length: 0, each: function () {} };
            },
            attr: function () { return ""; },
            each: function () {},
        };
    },
};

export default cheerio;